// The converter module's Web Worker (P11-X1): `app-notes-convert-wasm` is instantiated here, so a long import or
// export never blocks the page (typing, scrolling and the progress toast stay live) and Cancel can stop it by
// terminating the worker. Messages: `{id, fn, args}` → `{id, ok}` (bytes / string, transferred) or `{id, err}` (the
// module's thrown JSON error reply, or a message). `{id, fn: "ping"}` answers once the module is ready; a failed load
// is `{id, err, load: true}`.

// @ts-ignore -- generated by `pnpm build:wasm`
import init, * as mod from "../../src-wasm-convert/pkg/app_notes_convert_wasm.js";

type Fn = "ping" | "import_file" | "export_file" | "paste_html";
interface Call {
  id: number;
  fn: Fn;
  args: unknown[];
}

const scope = self as unknown as {
  onmessage: ((ev: MessageEvent<Call>) => void) | null;
  postMessage(msg: unknown, transfer?: Transferable[]): void;
};

const ready: Promise<unknown> = (init as () => Promise<unknown>)();
const fns = mod as unknown as Record<Fn, (...args: unknown[]) => unknown>;

scope.onmessage = (ev) => {
  const { id, fn, args } = ev.data;
  ready.then(
    () => {
      try {
        const out = fns[fn](...args);
        scope.postMessage({ id, ok: out }, out instanceof Uint8Array ? [out.buffer] : []);
      } catch (e) {
        scope.postMessage({ id, err: typeof e === "string" ? e : e instanceof Error ? e.message : String(e) });
      }
    },
    (e: unknown) => scope.postMessage({ id, err: e instanceof Error ? e.message : String(e), load: true }),
  );
};
